      "number": 35,
      "arFull": "وَقَالَ الَّذِیْنَ اَشْرَكُوْا لَوْ شَآءَ اللّٰهُ مَا عَبَدْنَا مِنْ دُوْنِهٖ مِنْ شَیْءٍ نَّحْنُ وَلَاۤ اٰبَآؤُنَا وَلَا حَرَّمْنَا مِنْ دُوْنِهٖ مِنْ شَیْءٍ ؕ كَذٰلِكَ فَعَلَ الَّذِیْنَ مِنْ قَبْلِهِمْ ۚ فَهَلْ عَلَی الرُّسُلِ اِلَّا الْبَلٰغُ الْمُبِیْنُ ۟",
      "ur": "مشرک لوگوں نے کہا کہ اگر اللہ تعالیٰ چاہتا تو ہم اور ہمارے باپ دادے اس کے سوا کسی اور کی عبادت ہی نہ کرتے، نہ اس کے فرمان کے بغیر کسی چیز کو حرام کرتے۔ یہی فعل ان سے پہلے کے لوگوں کا رہا۔ تو رسولوں پر تو صرف کھلم کھلا پیغام کا پہنچا دینا ہے.[1]",
