      "number": 53,
      "arFull": "وَمَا بِكُمْ مِّنْ نِّعْمَةٍ فَمِنَ اللّٰهِ ثُمَّ اِذَا مَسَّكُمُ الضُّرُّ فَاِلَیْهِ تَجْـَٔرُوْنَ ۟ۚ",
