      "arFull": "وَیَجْعَلُوْنَ لِمَا لَا یَعْلَمُوْنَ نَصِیْبًا مِّمَّا رَزَقْنٰهُمْ ؕ تَاللّٰهِ لَتُسْـَٔلُنَّ عَمَّا كُنْتُمْ تَفْتَرُوْنَ ۟",
