      "arFull": "وَمِنْ ثَمَرٰتِ النَّخِیْلِ وَالْاَعْنَابِ تَتَّخِذُوْنَ مِنْهُ سَكَرًا وَّرِزْقًا حَسَنًا ؕ اِنَّ فِیْ ذٰلِكَ لَاٰیَةً لِّقَوْمٍ یَّعْقِلُوْنَ ۟",
