      "arFull": "وَلَا تَشْتَرُوْا بِعَهْدِ اللّٰهِ ثَمَنًا قَلِیْلًا ؕ اِنَّمَا عِنْدَ اللّٰهِ هُوَ خَیْرٌ لَّكُمْ اِنْ كُنْتُمْ تَعْلَمُوْنَ ۟",
      "ur": "تم اللہ کے عہد کو تھوڑے مول کے بدلے نہ بیچ دیا کرو۔ یاد رکھو اللہ کے پاس کی چیز ہی تمہارے لیے بہتر ہے بشرطیکہ تم میں علم ہو.",
