      "arFull": "مَنْ كَفَرَ بِاللّٰهِ مِنْ بَعْدِ اِیْمَانِهٖۤ اِلَّا مَنْ اُكْرِهَ وَقَلْبُهٗ مُطْمَىِٕنٌّۢ بِالْاِیْمَانِ وَلٰكِنْ مَّنْ شَرَحَ بِالْكُفْرِ صَدْرًا فَعَلَیْهِمْ غَضَبٌ مِّنَ اللّٰهِ ۚ وَلَهُمْ عَذَابٌ عَظِیْمٌ ۟",
