      "arFull": "وَعَلَی الَّذِیْنَ هَادُوْا حَرَّمْنَا مَا قَصَصْنَا عَلَیْكَ مِنْ قَبْلُ ۚ وَمَا ظَلَمْنٰهُمْ وَلٰكِنْ كَانُوْۤا اَنْفُسَهُمْ یَظْلِمُوْنَ ۟",
