      "arFull": "اِنَّ اِبْرٰهِیْمَ كَانَ اُمَّةً قَانِتًا لِّلّٰهِ حَنِیْفًا ؕ وَلَمْ یَكُ مِنَ الْمُشْرِكِیْنَ ۟ۙ",
