      "arFull": "وَاٰتَیْنٰهُ فِی الدُّنْیَا حَسَنَةً ؕ وَاِنَّهٗ فِی الْاٰخِرَةِ لَمِنَ الصّٰلِحِیْنَ ۟ؕ",
